import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
public class OrderServiceLegacy {
  private final OrderRepository orderRepo;

  public OrderServiceLegacy(OrderRepository orderRepo) {
    this.orderRepo = orderRepo;
  }

  @Transactional
  public void printCustomers() {
    List<Order> orders = orderRepo.findAll(); // ❌ OLD: 1 query (lazy customer)
    for (Order o : orders) {
      // ❌ OLD: each access fires a separate SELECT on the customer —
      // with 1000 orders that is 1 + 1000 queries (the N+1 problem),
      // which tanks latency and DB load.
      Customer c = o.getCustomer(); // ❌ OLD: N extra queries
      System.out.println(c.getName());
    }
  }
}

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.EntityGraph;
import java.util.List;

public interface OrderRepository extends JpaRepository<Order, Long> {
  // ✅ NEW: the entity graph tells JPA to fetch customer eagerly in
  // the SAME query (via a join), so accessing o.getCustomer() costs
  // no extra SQL.
  @EntityGraph(attributePaths = "customer") // ✅ NEW
  List<Order> findAll();
}

